create type public.app_role as enum ('admin','moderator');
create type public.request_status as enum ('pendiente','en_revision','aceptada','rechazada','archivada');
create type public.message_status as enum ('nuevo','leido','respondido','archivado');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null, created_at timestamptz not null default now(), unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role; alter table public.user_roles enable row level security;
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke all on function public.has_role(uuid,public.app_role) from public; grant execute on function public.has_role(uuid,public.app_role) to anon,authenticated,service_role;
create policy "Users read own roles" on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create function public.admin_exists() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where role='admin') $$;
revoke all on function public.admin_exists() from public; grant execute on function public.admin_exists() to anon,authenticated,service_role;
create function public.touch_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
create table public.applications (id uuid primary key default gen_random_uuid(),alias text not null check(char_length(alias) between 2 and 60),age integer not null check(age between 14 and 99),contact_channel text not null check(char_length(contact_channel) between 2 and 40),contact_handle text not null check(char_length(contact_handle) between 2 and 100),email text not null check(char_length(email) between 5 and 255 and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),introduction text not null check(char_length(introduction) between 20 and 2000),motivation text not null check(char_length(motivation) between 20 and 2000),availability text check(availability is null or char_length(availability)<=1000),privacy_accepted boolean not null check(privacy_accepted=true),status public.request_status not null default 'pendiente',reviewed boolean not null default false,admin_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant insert on public.applications to anon,authenticated; grant select,update,delete on public.applications to authenticated; grant all on public.applications to service_role; alter table public.applications enable row level security;
create policy "Public submits applications" on public.applications for insert to anon,authenticated with check(status='pendiente' and reviewed=false and admin_notes is null);
create policy "Admins read applications" on public.applications for select to authenticated using(public.has_role(auth.uid(),'admin'));
create policy "Admins update applications" on public.applications for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create policy "Admins delete applications" on public.applications for delete to authenticated using(public.has_role(auth.uid(),'admin'));
create trigger applications_touch before update on public.applications for each row execute function public.touch_updated_at();
create table public.alliances (id uuid primary key default gen_random_uuid(),organization_name text not null check(char_length(organization_name) between 2 and 100),representative text not null check(char_length(representative) between 2 and 80),proposal_type text not null check(char_length(proposal_type) between 2 and 60),description text not null check(char_length(description) between 20 and 3000),contact_channel text not null check(char_length(contact_channel) between 2 and 100),email text not null check(char_length(email) between 5 and 255 and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),additional_info text check(additional_info is null or char_length(additional_info)<=1500),privacy_accepted boolean not null check(privacy_accepted=true),status public.request_status not null default 'pendiente',reviewed boolean not null default false,admin_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant insert on public.alliances to anon,authenticated; grant select,update,delete on public.alliances to authenticated; grant all on public.alliances to service_role; alter table public.alliances enable row level security;
create policy "Public submits alliances" on public.alliances for insert to anon,authenticated with check(status='pendiente' and reviewed=false and admin_notes is null);
create policy "Admins read alliances" on public.alliances for select to authenticated using(public.has_role(auth.uid(),'admin'));
create policy "Admins update alliances" on public.alliances for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create policy "Admins delete alliances" on public.alliances for delete to authenticated using(public.has_role(auth.uid(),'admin'));
create trigger alliances_touch before update on public.alliances for each row execute function public.touch_updated_at();
create table public.contact_messages (id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 80),email text not null check(char_length(email) between 5 and 255 and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),reason text not null check(char_length(reason) between 2 and 60),subject text not null check(char_length(subject) between 3 and 150),message text not null check(char_length(message) between 10 and 3000),privacy_accepted boolean not null check(privacy_accepted=true),status public.message_status not null default 'nuevo',admin_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant insert on public.contact_messages to anon,authenticated; grant select,update,delete on public.contact_messages to authenticated; grant all on public.contact_messages to service_role; alter table public.contact_messages enable row level security;
create policy "Public submits messages" on public.contact_messages for insert to anon,authenticated with check(status='nuevo' and admin_notes is null);
create policy "Admins read messages" on public.contact_messages for select to authenticated using(public.has_role(auth.uid(),'admin'));
create policy "Admins update messages" on public.contact_messages for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create policy "Admins delete messages" on public.contact_messages for delete to authenticated using(public.has_role(auth.uid(),'admin'));
create trigger contact_messages_touch before update on public.contact_messages for each row execute function public.touch_updated_at();
create table public.announcements (id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 3 and 160),category text not null default 'General' check(char_length(category) between 2 and 40),excerpt text check(excerpt is null or char_length(excerpt)<=300),content text not null check(char_length(content) between 1 and 20000),image_url text,published boolean not null default false,published_at timestamptz,author_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select on public.announcements to anon; grant select,insert,update,delete on public.announcements to authenticated; grant all on public.announcements to service_role; alter table public.announcements enable row level security;
create policy "Public reads published announcements" on public.announcements for select to anon,authenticated using(published=true or public.has_role(auth.uid(),'admin'));
create policy "Admins insert announcements" on public.announcements for insert to authenticated with check(public.has_role(auth.uid(),'admin'));
create policy "Admins update announcements" on public.announcements for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create policy "Admins delete announcements" on public.announcements for delete to authenticated using(public.has_role(auth.uid(),'admin'));
create trigger announcements_touch before update on public.announcements for each row execute function public.touch_updated_at();
create index announcements_published_idx on public.announcements(published,published_at desc);
create table public.site_settings (key text primary key check(key ~ '^[a-z0-9_]{2,60}$'),value text not null default '' check(char_length(value)<=2000),updated_at timestamptz not null default now());
grant select on public.site_settings to anon; grant select,insert,update,delete on public.site_settings to authenticated; grant all on public.site_settings to service_role; alter table public.site_settings enable row level security;
create policy "Public reads settings" on public.site_settings for select to anon,authenticated using(true);
create policy "Admins insert settings" on public.site_settings for insert to authenticated with check(public.has_role(auth.uid(),'admin'));
create policy "Admins update settings" on public.site_settings for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create policy "Admins delete settings" on public.site_settings for delete to authenticated using(public.has_role(auth.uid(),'admin'));
create trigger site_settings_touch before update on public.site_settings for each row execute function public.touch_updated_at();